import html
CSS='''*{box-sizing:border-box}body{margin:0;background:#f4f6f9;color:#22334a;font:15px/1.55 Inter,Segoe UI,Arial,sans-serif}aside{position:fixed;inset:0 auto 0 0;width:230px;background:#14283c;color:#fff;padding:30px 22px}aside strong{font-size:21px;letter-spacing:.04em}aside small{display:block;color:#a9becf;margin-bottom:35px}aside a{display:block;color:#d7e4ee;text-decoration:none;padding:12px;border-radius:8px;margin:4px 0}aside a:hover{background:#28455c}main{margin-left:230px;padding:36px;max-width:1500px}header{margin-bottom:25px}h1{font-size:32px;letter-spacing:-1px;margin:5px 0}h2{font-size:20px;margin:0 0 12px}h3{font-size:16px}small{color:#63778b;letter-spacing:.04em}section,.metric,.report{background:white;border:1px solid #e0e6ed;border-radius:14px;padding:22px;margin-bottom:20px;box-shadow:0 3px 12px #152b4008}.metrics,.reports{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.metric strong{display:block;font-size:30px;color:#173c51}.report{margin:0;padding:18px}.report h3{min-height:48px}.actions,.import{display:flex;align-items:center;flex-wrap:wrap;gap:12px}.import{padding:15px 0;border-bottom:1px solid #e5eaf0}.import b{min-width:155px}button,.btn{background:#176c68;color:white;border:0;border-radius:8px;padding:10px 16px;font:inherit;font-weight:600;text-decoration:none;cursor:pointer;display:inline-block}.secondary{background:#e8f0f3;color:#25475a}a{color:#176c68}input,select{max-width:100%;padding:10px;border:1px solid #cbd5df;border-radius:7px;background:white;color:inherit;font:inherit}label{display:block;color:#526578;font-size:13px;margin-bottom:10px}label input{display:block;width:100%}.notice{background:#fff8e8;color:#79561b;padding:12px;border-radius:8px}.table-wrap,section{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px;margin-top:15px}td,th{padding:12px;text-align:left;border-bottom:1px solid #e0e6ed}th{background:#edf2f6;white-space:nowrap}footer{color:#64788b;font-size:12px;margin-top:30px}@media(max-width:850px){aside{position:static;width:auto;padding:16px}aside small{margin:0}aside a{display:inline-block;padding:6px}main{margin:0;padding:18px}.metrics,.reports{grid-template-columns:repeat(auto-fit,minmax(180px,1fr))}}'''
def page(title,body):
 return '<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+' | IT Inventory</title><style>'+CSS+'</style></head><body><aside><strong>IT INVENTORY</strong><small>KAWASAN BERIKAT</small><nav><a href="/">Dashboard</a><a href="/#integrasi">Integrasi Accurate</a><a href="/#import">Import data</a><a href="/#laporan">Laporan Bea Cukai</a></nav></aside><main><header><small>IT INVENTORY / PROFESSIONAL EDITION</small><h1>'+html.escape(title)+'</h1></header>'+body+'<footer>v2.4 Review Mutasi · Satu instalasi per perusahaan · Laporan draft</footer></main></body></html>'
